package com.shopsphere.controller; import com.shopsphere.dto.AuthDtos.*; import com.shopsphere.service.ProductService; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/products") public class ProductController {private final ProductService service;public ProductController(ProductService s){service=s;} @GetMapping public Page<ProductResponse> search(@RequestParam(required=false)String q,@RequestParam(required=false)UUID categoryId,Pageable page){return service.search(q,categoryId,page);} @GetMapping("/{id}") public ProductResponse get(@PathVariable UUID id){return service.get(id);} @PostMapping @PreAuthorize("hasRole('ADMIN')") public ProductResponse create(@Valid @RequestBody ProductRequest r){return service.create(r);} @DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public void delete(@PathVariable UUID id){service.delete(id);}}